            "length": "14 - 16 feet"
        },
        "midsize": {
            "name": "Midsize",
            "heightRange": "5'3\" - 5'5\"",
            "length": "16 - 18 feet"
        },
        "fullsize": {
            "name": "Fullsize",
            "heightRange": "5'6\" - 5'9\"",
            "length": "18 - 20 feet"
