 The following code should accomplish what you want:

<?php
function smart_sort_array($set,$order) {
    $keys = array("name","address","age");
    $tmp = array();
    foreach ($set as $key => $value) {
        if (!isset($tmp[$key])) {
            $tmp[$key] = array();
        }
        $tmp[$key][$keys[0]] = $value['name'];
        $tmp[$key][$keys[1]] = $value['address'];
        $tmp[$key][$keys[2]] = $value['age'];
    }
    uasort($tmp, function($a,$b) {
        return strcmp(strtolower($a[$keys[0]],strtolower($b[$keys[0]])),$order);
    });
    return $tmp;
}
?>

