response:
1. Add the following function to your script
function createTigerList($tiger) {
$output = '';
if ($tiger['isMale'] == true) {
$output .= "male";
} else if ($tiger['isFemale'] == true) {
$output .= "female";
$output .= "sex";
$output .= $tiger['furColor'];
$output .= "skin";
$output .= $tiger['eyes'];
$output .= $tiger['nose'];
$output .= $tiger['teeth'];
$output .= $tiger['claws'];
$output .= $tiger['legs'];
$output .= $tiger['tail'];
return $output;

