The following code shows how you can define the RedisClient class using JavaScript:

class RedisClient {
    // Constructor - Creates the client object
    constructor(redisHostname, redisPort, redisPassword) {
        this._host = redisHostname;
        this._port = redisPort;
        this._password = redisPassword;

        // Create the client object
        this._client = new RedisClient();
    }

    /**
     * Get a value from Redis
     * @param {string} key   - Key name
     * @return {Promise}      - A promise that resolves when the result is returned from Redis
     */
    async get(key) {
        return await this._client.get(key);
    }

    /**
     * Set a value into Redis
     * @param {string} key   - Key name
     * @param {string} value - Value to set
     * @param {number} ttl   - Time to live in seconds
     * @return {Promise}      - A promise that resolves when the result is returned from Redis
