import React from "react";
import { Component } from "react";
import { useState } from "react";
import "./App.css";

function App() {
  const [registrations, setRegistrations] = useState({});

  // handle data being added to the state
  const addDataToState = (data) => {
    setRegistrations((oldState) => ({ ...oldState, ...data }));
  };

  return (
    <div>
      <h1>Adding data</h1>
      <button onClick={() => addDataToState({ key: "first", value: "one" })}>add</button>
      <button onClick={() => addDataToState({ key: "second", value: "two" })}>add</button>
      <p>{JSON.stringify(registrations)}</p>
    </div>
  );
}

